def any_phrase(t,xs):
    for x in xs:
        if x in t:
            return True
    return False

def has_word(t,p):
    return re.search(p,t,re.I) is not None

def add_statement(out,term,ids):
    for s in out:
        if s.get('term')==term:
            return
    out.append({'term':term,'support_ids':ids})

def add_once(xs,x):
    if x not in xs:
        xs.append(x)

def make_union(xs):
    if len(xs)==1:
        return xs[0]
    v=xs[len(xs)-1]
    i=len(xs)-2
    while i>=0:
        v=['participant_union',xs[i],v]
        i-=1
    return v

def make_condition(t):
    cs=[]
    if 'need to know' in t or 'need-to-know' in t or 'need-to know' in t:
        cs.append(['need_to_know','stated purpose'])
    if any_phrase(t,['bound by obligations of confidentiality','treat the confidential information as confidential','obliged by their contracts','obligated to protect','terms and conditions no less protective']):
        cs.append(['confidentiality_bound','source-stated confidentiality obligation'])
    if any_phrase(t,['only to the extent necessary','disclosure is necessary','as deemed necessary','reasonably necessary']):
        cs.append(['extent_necessary','source-stated purpose'])
    if not cs:
        return ['no_condition']
    v=cs[0]
    i=1
    while i<len(cs):
        v=['and_condition',v,cs[i]]
        i+=1
    return v

def permission_segment(t):
    marks=['may disclose','may share','internally share','restrict access','except in confidence','except to such']
    best=-1
    for m in marks:
        p=t.rfind(m)
        if p>best:
            best=p
    if best<0 and 'not to disclose' in t and ' except ' in t:
        best=t.rfind(' except ')
    return t[best:] if best>=0 else t

def recipient_terms(t):
    owner=['receiving_party']
    if any_phrase(t,["affiliates' officers","affiliates’ officers","affiliate's officers","affiliate’s officers"]):
        owner=['affiliates_of',['receiving_party']]
    xs=[]
    if has_word(t,r'\bemployees?\b'):
        xs.append(['employees_of',owner])
    if has_word(t,r'\bdirectors?\b'):
        xs.append(['directors_of',owner])
    if has_word(t,r'\bofficers?\b'):
        xs.append(['officers_of',owner])
    if any_phrase(t,['legal advisors','legal advisers','attorneys','legal counsel']):
        xs.append(['legal_advisors_of',owner])
    if any_phrase(t,['financial advisors','financial advisers']):
        xs.append(['financial_advisors_of',owner])
    if any_phrase(t,['professional advisors','professional advisers']):
        xs.append(['professional_advisors_of',owner])
    if has_word(t,r'\baccountants?\b'):
        xs.append(['accountants_of',owner])
    if has_word(t,r'\bconsultants?\b'):
        xs.append(['consultants_of',owner])
    if has_word(t,r'\bagents?\b'):
        xs.append(['agents_of',owner])
    if has_word(t,r'\bcontractors?\b'):
        xs.append(['independent_contractors_of',owner])
    if has_word(t,r'\blenders?\b'):
        xs.append(['lenders_of',owner])
    if 'internally share' in t and not xs:
        xs.append(['internal_personnel_of',['receiving_party']])
    if not xs and 'representatives' in t:
        xs.append(['representatives_of',['receiving_party']])
    if not xs and any_phrase(t,['third parties','third party']):
        xs.append(['third_parties'])
    return xs

def make_exceptions(t,perm):
    es=[]
    if any_phrase(t,['prior written consent','prior, written consent','prior written approval','prior written permission','expressly authorized in writing','express permission']):
        es.append(['authorization_exception','source-stated written authorization'])
    if any_phrase(t,['required to analyze','required to fulfil','required to fulfill']):
        es.append(['purpose_exception','source-stated required activity'])
    if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
        es.append(['cross_reference_exception','source-stated disclosure cross-reference'])
    if perm is not None:
        es.append(['permission_exception',perm])
    if not es:
        return ['no_exceptions']
    v=['exception_set',es[0]]
    i=1
    while i<len(es):
        v=['add_exception',v,es[i]]
        i+=1
    return v

def parse_context(raw,ids,out,refs):
    t=raw.casefold()
    if not t:
        return
    if ('“representative” means' in t or '"representative" means' in t or 'representative means' in t) and any_phrase(t,['employee','director','officer','agent','accountant','attorney','contractor']):
        cats=recipient_terms(t)
        fixed=[]
        for c in cats:
            if len(c)>1:
                c[1]=['party']
            fixed.append(c)
        if fixed:
            add_statement(out,['define_representative',['party'],make_union(fixed)],ids)
    if any_phrase(t,['information about employees','employee lists and records','human resources data']) and 'confidential' in t:
        add_statement(out,['confidential_information_includes',['employee_information',['disclosing_party']]],ids)
    if 'whereas' in t and 'may' in t and 'disclos' in t and 'confidential information' in t:
        add_statement(out,['possible_disclosure_description',['disclosing_party'],['confidential_information'],['receiving_party']],ids)
    if 'confidential information' not in t and 'such information' not in t and 'the same' not in t:
        return
    actor=['named_recipient','Volunteer'] if 'volunteer agrees' in t else ['receiving_party']
    if 'neither it nor its representatives' in t and any_phrase(t,['any other person','any other organization','other person or organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        ex=make_exceptions(t,None)
        add_statement(out,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],ex],ids)
        return
    pmark=any_phrase(t,['may disclose','may share','internally share','restrict access']) or ('not to disclose' in t and ' except ' in t)
    perm=None
    if pmark:
        seg=permission_segment(t)
        cats=recipient_terms(seg)
        if cats:
            perm=['permission',actor,['disclose',['confidential_information'],make_union(cats)],make_condition(t)]
            add_statement(out,perm,ids)
    third=any_phrase(t,['third parties','third party'])
    neg=any_phrase(t,['shall not disclose','not to disclose','not to, without','not to, directly','not disclose, allow access','not to divulge'])
    if third and neg:
        ex=make_exceptions(t,perm)
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],ids)
        if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
            add_once(refs,'unresolved disclosure cross-reference')

def has_tag(term,name):
    todo=[term]
    while todo:
        x=todo.pop()
        if isinstance(x,list) and x:
            if x[0]==name:
                return True
            i=1
            while i<len(x):
                if isinstance(x[i],list):
                    todo.append(x[i])
                i+=1
    return False

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    statements=[]
    refs=[]
    texts=[]
    ids=[]
    for s in spans:
        raw=s.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        texts.append(raw)
        ids.append(s.get('id'))
        parse_context(raw,[s.get('id')],statements,refs)
        parse_disposal(raw,[s.get('id')],statements)
    i=0
    while i+1<len(texts):
        w=texts[i]+' '+texts[i+1]
        lw=w.casefold()
        if ('restrict access' in lw and 'such employees' in lw) or ('neither it nor its representatives' in lw and any_phrase(lw,['any other person','other person or organization'])):
            parse_context(w,[ids[i],ids[i+1]],statements,refs)
        i+=1
    has_permission=False
    has_definition=False
    needs_definition=False
    for s in statements:
        term=s.get('term')
        if isinstance(term,list) and term:
            if term[0]=='permission' or has_tag(term,'permission_exception'):
                has_permission=True
            if term[0]=='define_representative':
                has_definition=True
            if term[0] in ('permission','prohibition') and has_tag(term,'representatives_of'):
                needs_definition=True
    unresolved=[]
    if refs and not has_permission:
        unresolved.append('A disclosure exception refers to another provision, but no operative recipient permission was resolved from the current source.')
    if needs_definition and not has_definition:
        unresolved.append('An operative norm uses Representatives, but their current-source membership or owner binding was not resolved.')
    return {'statements':statements,'complete':not unresolved,'unresolved':unresolved}

def make_information_bundle(xs):
    if len(xs)==1:
        return xs[0]
    v=xs[len(xs)-1]
    i=len(xs)-2
    while i>=0:
        v=['information_bundle',xs[i],v]
        i-=1
    return v

def disposal_information(t):
    xs=[['confidential_information']]
    if 'copy' in t or 'copies' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['compilation','analysis','derivative work','notes or abstracts','notes and abstracts']):
        xs.append(['derivative_materials_of',['confidential_information']])
    return make_information_bundle(xs)

def retention_information(t):
    xs=[]
    if 'copy' in t or 'copies' in t or 'backup system' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['notes or abstracts','notes and abstracts','compilation','analysis','derivative work']):
        xs.append(['derivative_materials_of',['confidential_information']])
    if not xs:
        xs.append(['confidential_information'])
    return make_information_bundle(xs)

def disposal_trigger(t):
    xs=[]
    if 'termination of service' in t or 'service terminates' in t:
        xs.append(['service_termination'])
    elif any_phrase(t,['upon termination of this agreement','upon termination of the agreement','termination of this agreement']):
        xs.append(['agreement_termination'])
    if 'completion of the purpose' in t:
        xs.append(['purpose_completion'])
    if (('upon' in t and 'request' in t) or 'receipt of a written request' in t or 'written request from' in t or 'written request of' in t):
        xs.append(['request_by',['disclosing_party']])
    if not xs:
        return None
    v=xs[0]
    i=1
    while i<len(xs):
        v=['trigger_alternative',v,xs[i]]
        i+=1
    return v

def retention_condition_for(t):
    if 'required' in t and 'applicable law' in t:
        return ['retention_condition','record copy required by applicable law']
    if 'archival purpose' in t:
        return ['retention_condition','one copy solely for archival purpose']
    if 'single copy' in t and any_phrase(t,['regulatory compliance','compliance with the terms']):
        return ['retention_condition','single copy for regulatory and agreement compliance']
    if 'single copy' in t:
        return ['retention_condition','single copy for the source-stated purpose']
    return ['retention_condition','source-stated limited retention']

def parse_disposal(raw,ids,out):
    t=raw.casefold()
    if not t:
        return
    actor=['named_recipient','Volunteer'] if 'volunteer' in t else ['receiving_party']
    explicit_retention=any_phrase(t,['may retain','may maintain a single copy'])
    cond=retention_condition_for(t)
    if explicit_retention:
        add_statement(out,['retention_permission',actor,retention_information(t),['after_disposal'],cond],ids)
    if 'retained' in t and any_phrase(t,['no copies','no copy','no copies, electronic or otherwise']):
        add_statement(out,['retention_prohibition',actor,retention_information(t),['after_disposal']],ids)
    trigger=disposal_trigger(t)
    if trigger is None:
        return
    do_return=re.search(r'\breturn(?:ed|ing)?\b',t,re.I) is not None
    do_destroy=re.search(r'\bdestroy(?:ed|ing)?\b',t,re.I) is not None and 'not destroyed' not in t
    if not do_return and not do_destroy:
        return
    info=disposal_information(t)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    es=[]
    if 'unless otherwise instructed in writing' in t:
        es.append(['authorization_exception','different written instructions from the disclosing participant'])
    if explicit_retention:
        es.append(['retention_exception',actor,retention_information(t),cond])
    if not es:
        exceptions=['no_exceptions']
    else:
        exceptions=['exception_set',es[0]]
        i=1
        while i<len(es):
            exceptions=['add_exception',exceptions,es[i]]
            i+=1
    add_statement(out,['disposal_obligation',actor,action,trigger,exceptions],ids)

fact_encoder_source:
"""Lossless source inputs plus grounded, fallible learned observations for G.

This is an interface, not a legal extractor. Existing acquired source programs
remain upstream readers; all their supplied output and current text are retained.
The relational learner cannot execute arbitrary Python on text. Its search bias
must not be confused with an impossibility claim about an old raw-text reader.
"""
from copy import deepcopy

from .objects import digest
from .semantic_operations import ground_answers
from .span_compiler import occurrences
from .unit_evidence import TRANSPORT, ground_selected_units


def fact(predicate,*arguments):
    return {'predicate':predicate,'arguments':list(arguments),'sign':'positive'}


SIGNATURES = {
    'source_text':(['text'],'observed'),
    'source_unit':(['unit'],'observed'),
    'unit_text':(['unit','text'],'observed'),
    'next_unit':(['unit','unit'],'observed'),
    'json_root':(['field','json_node'],'observed'),
    'json_kind':(['json_node','json_kind'],'observed'),
    'json_entry':(['json_node','field','json_node'],'observed'),
    'json_item':(['json_node','position','json_node'],'observed'),
    'json_scalar':(['json_node','scalar'],'observed'),
    'legacy_root':(['term'],'observed'),
    'term_constructor':(['term','constructor'],'observed'),
    'term_child':(['term','position','term'],'observed'),
    'term_scalar':(['term','scalar'],'observed'),
    'root_support':(['term','unit'],'observed'),
    'reader_query':(['query','operation'],'observed'),
    'query_window':(['query','unit'],'observed'),
    'query_focus':(['query','unit'],'observed'),
    'reader_observed_value':(['query','choice'],'observed'),
    'query_choice':(['query','choice'],'observed'),
    'query_unknown':(['query'],'observed'),
    'query_unread':(['query'],'observed'),
    'evidence_unit':(['query','unit'],'observed'),
    'evidence_quote':(['query','unit','text'],'observed'),
}


def signatures():
    return {p:{'arguments':list(args),'kind':kind} for p,(args,kind) in SIGNATURES.items()}


def encode_source_observations(source_id, *, source_text, units, source_output,
                               operations, queries, answers, scope, query_scopes=None,
                               complete_source_absence_choices=None):
    """Retain every G-visible value, including order, text and unknown/unread.

    Only the actual answered subset is quote-grounded. Completion branches are
    solver possibilities, not asserted readings; an empty branch preserves the
    possibility that no declared choice describes an unread meaning.
    Native labels/source review enter separate constraints, never these inputs.
    """
    if not isinstance(source_id,str) or not source_id or not isinstance(source_text,str):
        raise ValueError('A source identity and its actual text are required')
    if scope not in ('focus_last','window'):
        raise ValueError('Preserve the actual acquired focus/window contract')
    # Validate operation structure without interpreting demonstrations as current
    # facts. Their original-parent validation belongs to asset acquisition.
    import jsonschema
    from .semantic_operations import OPERATION
    jsonschema.validate(operations,{'type':'array','items':OPERATION})
    ops={o['name']:o for o in operations};by_unit={u['id']:u for u in units}
    if len(ops)!=len(operations) or len(by_unit)!=len(units):
        raise ValueError('Distinct acquired operations and actual source units required')
    for op in operations:
        choices=[c['name'] for c in op['choices']]
        if len(set(choices))!=len(choices) or 'unknown' in choices:
            raise ValueError('Declared distinct choices; unknown is reserved')
    for u in units:
        if type(u['id']) is not int or u['id']<0 or not occurrences(source_text,u['text']):
            raise ValueError('Units must quote the actual current source')
    by_query={q['id']:q for q in queries}
    if len(by_query)!=len(queries) or any(not isinstance(q['id'],str) or not q['id'] for q in queries):
        raise ValueError('Distinct current queries required')
    if query_scopes is not None and (set(query_scopes)!=set(by_query) or any(v not in ('focus_last','window') for v in query_scopes.values())):
        raise ValueError('Record the actual scope of every current query')
    for q in queries:
        if q['operation'] not in ops or not q['unit_ids'] or len(set(q['unit_ids']))!=len(q['unit_ids']) \
                or not set(q['unit_ids'])<=set(by_unit):
            raise ValueError('Each actual query needs its declared operation and current window')
    ids=[a['id'] for a in answers]
    if len(set(ids))!=len(ids) or not set(ids)<=set(by_query):
        raise ValueError('At most one actual answer per planned query')
    grounded=[]
    for original in answers:
        answer={k:deepcopy(original[k]) for k in ('id','choice','evidence')}
        answer['evidence']=[{k:w[k] for k in ('unit_id','quote')} for w in answer['evidence']]
        query=by_query[answer['id']]
        actual_scope=query_scopes[query['id']] if query_scopes is not None else scope
        if 'evidence_transport' in original:
            if original['evidence_transport']!=TRANSPORT:
                raise ValueError('Undeclared source evidence transport')
            reread=ground_selected_units(operations,[query],units,{'answers':{query['id']:{
                'choice':answer['choice'],'evidence_unit_ids':original['selected_evidence_unit_ids']}}},
                scope=actual_scope,complete_source_absence_choices=complete_source_absence_choices)
            expected=[{k:w[k] for k in ('unit_id','quote')} for w in reread[0]['evidence']]
            if answer['evidence']!=expected:
                raise ValueError('Selected-unit evidence must retain its actual whole current unit')
            grounded.extend(reread)
        else:
            grounded.extend(ground_answers(operations,[query],units,{'answers':[answer]},scope=actual_scope,
                complete_source_absence_choices=complete_source_absence_choices))
    by_answer={a['id']:a for a in grounded}
    visible={'source_text':source_text,'units':deepcopy(units),'source_output':deepcopy(source_output),
        'operations':deepcopy(operations),'queries':deepcopy(queries),'answers':grounded,'scope':scope}
    if query_scopes is not None:visible['query_scopes']=deepcopy(query_scopes)
    if complete_source_absence_choices is not None:
        visible['complete_source_absence_choices']=deepcopy(complete_source_absence_choices)
    facts=[fact('source_text',source_text)];unknown=[];nodes={};roots={};term_supports={};json_count=0

    def json_tree(value):
        nonlocal json_count
        name='j'+str(json_count);json_count+=1
        kind='object' if isinstance(value,dict) else 'array' if isinstance(value,list) else 'null' if value is None else 'scalar'
        facts.append(fact('json_kind',name,kind))
        if isinstance(value,dict):
            for k,v in sorted(value.items()):facts.append(fact('json_entry',name,k,json_tree(v)))
        elif isinstance(value,list):
            for i,v in enumerate(value):facts.append(fact('json_item',name,i,json_tree(v)))
        elif value is not None:facts.append(fact('json_scalar',name,value))
        return name

    for key,value in visible.items():facts.append(fact('json_root',key,json_tree(value)))
    for i,u in enumerate(units):
        facts.extend([fact('source_unit',u['id']),fact('unit_text',u['id'],u['text'])])
        if i:facts.append(fact('next_unit',units[i-1]['id'],u['id']))

    def term_tree(value,supports):
        name='t'+str(len(nodes));nodes[name]=deepcopy(value);term_supports[name]=list(supports)
        if isinstance(value,list):
            if not value or not isinstance(value[0],str):raise ValueError('An existing term needs its acquired constructor')
            facts.append(fact('term_constructor',name,value[0]))
            for i,v in enumerate(value[1:]):facts.append(fact('term_child',name,i,term_tree(v,supports)))
        elif type(value) in (str,int,float,bool):facts.append(fact('term_scalar',name,value))
        else:raise ValueError('Unexpected existing typed term; do not coerce or fill it')
        return name

    for row in source_output['statements']:
        if not set(row['support_ids'])<=set(by_unit):raise ValueError('Legacy root cites a noncurrent unit')
        name=term_tree(row['term'],row['support_ids']);roots[name]=deepcopy(row);facts.append(fact('legacy_root',name))
        facts.extend(fact('root_support',name,u) for u in row['support_ids'])
    for q in queries:
        qid=q['id'];facts.append(fact('reader_query',qid,q['operation']))
        facts.extend(fact('query_window',qid,u) for u in q['unit_ids'])
        actual_scope=query_scopes[qid] if query_scopes is not None else scope
        if actual_scope=='focus_last':facts.append(fact('query_focus',qid,q['unit_ids'][-1]))
        a=by_answer.get(qid)
        if a:
            facts.append(fact('reader_observed_value',qid,a['choice']))
            for w in a['evidence']:
                facts.extend([fact('evidence_unit',qid,w['unit_id']),fact('evidence_quote',qid,w['unit_id'],w['quote'])])
        if a and a['choice']!='unknown':facts.append(fact('query_choice',qid,a['choice']))
        else:
            facts.append(fact('query_unknown' if a else 'query_unread',qid))
            unknown.append([[fact('query_choice',qid,c['name'])] for c in ops[q['operation']]['choices']]+[[]])
    context={'id':source_id,'facts':facts,'unknown_groups':unknown,'required':[],'forbidden':[]}
    return {'context':context,'visible_inputs':visible,'visible_inputs_sha256':digest(visible),
        'contract_sha256':digest({'version':1,'signatures':SIGNATURES,'scope':scope,
            'query_scope_policy':'explicit' if query_scopes is not None else 'global',
            'source_absence_policy':'explicit' if complete_source_absence_choices is not None else 'quoted_only',
            'raw_text_retained':True,'old_reader_is_upstream':True}),
        'legacy_roots':roots,'term_nodes':nodes,'term_supports':term_supports,
        'grounding_certifies_source_meaning':False,'new_model_requests':0}


def decode_visible_inputs(encoded):
    """Check that the generic relational view loses no supplied G input."""
    facts=encoded['context']['facts'];kind={};scalars={};entries={};items={};roots={}
    for a in facts:
        p=a['predicate'];args=a['arguments']
        if p=='json_kind':kind[args[0]]=args[1]
        elif p=='json_scalar':scalars[args[0]]=args[1]
        elif p=='json_entry':entries.setdefault(args[0],{})[args[1]]=args[2]
        elif p=='json_item':items.setdefault(args[0],{})[args[1]]=args[2]
        elif p=='json_root':roots[args[0]]=args[1]
    def read(node):
        k=kind[node]
        if k=='null':return None
        if k=='scalar':return scalars[node]
        if k=='object':return {key:read(child) for key,child in entries.get(node,{}).items()}
        return [read(child) for _,child in sorted(items.get(node,{}).items())]
    return {field:read(node) for field,node in roots.items()}


def retain_legacy_roots(encoded, outputs):
    """Render explicitly selected old roots; no default output on solver failure."""
    identities=[]
    for row in outputs:
        if row['predicate']!='keep_root':raise ValueError('Not a legacy-root selection output')
        identity,=row['arguments']
        if identity not in encoded['legacy_roots']:raise ValueError('Output names no actual current root')
        if identity not in identities:identities.append(identity)
    return [deepcopy(encoded['legacy_roots'][i]) for i in identities]

